<script>function previewProfileImage(input,id){const file=input.files&&input.files[0],img=document.getElementById(id);if(!file||!file.type.startsWith('image/'))return;const reader=new FileReader();reader.onload=e=>{img.src=e.target.result;img.classList.remove('hidden')};reader.readAsDataURL(file)}</script>
